mapper.insert:
INSERT INTO ANIMAL_DETAIL (
    ANIMAL_ID, ANIMAL_TYPE, ANIMAL_BREED, ANIMAL_NAME, ENTRANCE_DATE, ANIMAL_STATUS
) VALUES (
    (SELECT NVL(MAX(ANIMAL_ID), 0) + 1 FROM ANIMAL_DETAIL), 
    #{animalType},
    #{animalBreed},
    #{animalName},
    SYSDATE,
    #{animalStatus}
)

mapper.select:
SELECT * FROM (
    SELECT ROWNUM AS rn, a.* FROM (
        SELECT 
            ANIMAL_ID, ANIMAL_TYPE, ANIMAL_BREED, ANIMAL_NAME, ENTRANCE_DATE, ANIMAL_STATUS
        FROM ANIMAL_DETAIL

        ORDER BY ANIMAL_ID DESC
    ) a WHERE ROWNUM <= #{endRow}
) WHERE rn >= #{startRow}
